#include "continuous_runtime.h"
#include "demo_living_dynamics_v1.h"
#include "demo_personality_profiles.h"
#include <filesystem>
#include <fstream>
#include <string>
namespace fs = std::filesystem;
static void key(std::ostream& o,const char* n){o<<'"'<<n<<"\":";}
static void str(std::ostream& o,const std::string& s){o<<'"';for(char c:s){if(c=='"'||c=='\\')o<<'\\';o<<c;}o<<'"';}
static void outcome(std::ostream& o,const std::optional<WorldOutcome>& x){if(!x){o<<"null";return;}o<<"{";key(o,"accepted");o<<(x->accepted?"true":"false")<<",";key(o,"action");str(o,to_string(x->action));o<<",";key(o,"target");str(o,x->target_object_id);o<<",";key(o,"failure_reason");o<<static_cast<int>(x->failure_reason)<<",";key(o,"action_elapsed_minutes");o<<x->action_elapsed_minutes<<",";key(o,"task_effort_gained");o<<x->task_effort_gained<<",";key(o,"task_completed");o<<(x->task_completed?"true":"false")<<",";key(o,"plan_invalidated");o<<(x->plan_invalidated?"true":"false")<<",";key(o,"provenance");str(o,x->provenance);o<<"}";}
static void action(std::ostream& o,const std::optional<RunningAction>& x){if(!x){o<<"null";return;}o<<"{";key(o,"action");str(o,to_string(x->action));o<<",";key(o,"target");str(o,x->target_object_id);o<<",";key(o,"elapsed");o<<x->elapsed_minutes<<",";key(o,"planned");o<<x->planned_duration_minutes<<",";key(o,"status");str(o,to_string(x->status));o<<"}";}
static void facts(std::ostream& o,const Observation& x){o<<"[";for(size_t i=0;i<x.facts.size();++i){if(i)o<<",";o<<"{";key(o,"key");str(o,x.facts[i].key);o<<",";key(o,"value");str(o,x.facts[i].value);o<<"}";}o<<"]";}
static void deltas(std::ostream& o,const std::vector<ObservationFact>& x){o<<"[";for(size_t i=0;i<x.size();++i){if(i)o<<",";o<<"{";key(o,"key");str(o,x[i].key);o<<",";key(o,"value");str(o,x[i].value);o<<"}";}o<<"]";}
static void candidates(std::ostream& o,const DecisionContext& x){o<<"[";for(size_t i=0;i<x.candidates.size();++i){if(i)o<<",";const auto& c=x.candidates[i];o<<"{";key(o,"action");str(o,to_string(c.action));o<<",";key(o,"target");str(o,c.target_object_id);o<<",";key(o,"probability");o<<c.probability<<",";key(o,"eligible");o<<(c.eligible?"true":"false")<<"}";}o<<"]";}
static void reasons(std::ostream& o,const DecisionGate& x){o<<"[";for(size_t i=0;i<x.reasons.size();++i){if(i)o<<",";str(o,to_string(x.reasons[i]));}o<<"]";}
static void events(std::ostream& o,const std::vector<WorldEvent>& x){o<<"[";for(size_t i=0;i<x.size();++i){if(i)o<<",";o<<"{";key(o,"id");str(o,x[i].id);o<<",";key(o,"description");str(o,x[i].description);o<<"}";}o<<"]";}
static const char* commitment_status(const CharacterState& s){switch(s.commitment.status){case CommitmentStatus::Active:return "active";case CommitmentStatus::Suspended:return "suspended";default:return "none";}}
static void personality_json(std::ostream& o,const Personality& p){
    o<<"{";
    key(o,"procrastination");o<<p.procrastination<<",";
    key(o,"self_control");o<<p.self_control<<",";
    key(o,"rest_preference");o<<p.rest_preference<<",";
    key(o,"stimulation_seeking");o<<p.stimulation_seeking<<",";
    key(o,"task_anxiety_sensitivity");o<<p.task_anxiety_sensitivity<<",";
    key(o,"screen_strain_sensitivity");o<<p.screen_strain_sensitivity<<",";
    key(o,"need_response");o<<p.need_response<<",";
    key(o,"action_noise");o<<p.action_noise<<"}";
}
int main(int argc,char** argv){if(argc<4)return 2;const unsigned ss=static_cast<unsigned>(std::stoul(argv[1])),ps=static_cast<unsigned>(std::stoul(argv[2]));fs::path p=argv[3];fs::create_directories(p.parent_path());std::ofstream out(p);if(!out)return 3;World world(ss);world.time.minute_of_day=480;Observation observation=refresh_observation({},world,{});RuntimeScheduler scheduler(480);DemoLivingDynamicsV1 dynamics;ContinuousRuntime runtime(scheduler,world,observation,dynamics,{},ps);CharacterState state;const unsigned actor_id=ss>=1000?(ss-1000)/17:0;const std::string profile_id=argc>=5?argv[4]:DemoPersonalityProfiles::names()[actor_id%8];const Personality personality=DemoPersonalityProfiles::named(profile_id);runtime.submit_action_intent(ActionType::Idle,"",10);out<<"[";bool first=true;while(scheduler.now_total_minutes()<(ss>=1000?3360:840)){if(!first)out<<",";const bool bootstrap=first;first=false;auto r=runtime.execute_next_boundary(state,personality);out<<"{";key(out,"timestamp");out<<scheduler.now_total_minutes()<<",";key(out,"elapsed");out<<r.runtime.boundary.elapsed_minutes<<",";key(out,"scenario_seed");out<<ss<<",";key(out,"policy_seed");out<<ps<<",";key(out,"profile_id");str(out,profile_id);out<<",";key(out,"personality");personality_json(out,personality);out<<",";key(out,"dynamics_model");str(out,dynamics.identity());out<<",";key(out,"demo_only");out<<"true,";key(out,"bootstrap");out<<(bootstrap?"true":"false")<<",";key(out,"world_events");events(out,r.runtime.world_events);out<<",";key(out,"observation");out<<"{";key(out,"facts");facts(out,observation);out<<"},";key(out,"observation_deltas");deltas(out,r.observation_deltas);out<<",";key(out,"continuous_state_delta");out<<"{";key(out,"fatigue");out<<r.continuous_state.applied.fatigue<<",";key(out,"hunger");out<<r.continuous_state.applied.hunger<<",";key(out,"bathroom_urge");out<<r.continuous_state.applied.bathroom_urge<<"},";key(out,"impulse_state_delta");out<<"{";key(out,"fatigue");out<<r.impulse_state.applied.fatigue<<",";key(out,"hunger");out<<r.impulse_state.applied.hunger<<",";key(out,"bathroom_urge");out<<r.impulse_state.applied.bathroom_urge<<"},";key(out,"state");out<<"{";key(out,"boredom");out<<state.boredom<<",";key(out,"fatigue");out<<state.fatigue<<",";key(out,"task_pressure");out<<state.task_pressure<<",";key(out,"satisfaction");out<<state.satisfaction<<",";key(out,"hunger");out<<state.hunger<<",";key(out,"bathroom_urge");out<<state.bathroom_urge<<",";key(out,"anxiety");out<<state.anxiety<<",";key(out,"screen_strain");out<<state.screen_strain<<"},";key(out,"task_effort");out<<world.tasks.front().effort_done<<",";key(out,"effort_target");out<<world.tasks.front().effort_target<<",";key(out,"commitment_status");str(out,commitment_status(state));out<<",";key(out,"decision_gate");out<<"{";key(out,"open");out<<(r.runtime.boundary.decision_gate.open?"true":"false")<<",";key(out,"reasons");reasons(out,r.runtime.boundary.decision_gate);out<<"},";key(out,"policy_evaluated");out<<(r.policy_evaluated?"true":"false")<<",";key(out,"candidates");candidates(out,r.decision);out<<",";key(out,"running_action_before");action(out,r.running_action_before);out<<",";key(out,"running_action_after");action(out,r.running_action_after);out<<",";key(out,"selected_action");if(r.selected_action)str(out,to_string(*r.selected_action));else out<<"null";out<<",";key(out,"selected_target");str(out,r.selected_target_object_id);out<<",";key(out,"pre_policy_outcome");outcome(out,r.pre_policy_outcome);out<<",";key(out,"post_policy_outcome");outcome(out,r.post_policy_outcome);out<<",";key(out,"validation");out<<"{";key(out,"performed");out<<(r.replacement_validation_performed?"true":"false")<<",";key(out,"accepted");out<<(r.replacement_validation_accepted?"true":"false")<<"},";key(out,"provenance");str(out,"ContinuousRuntime::execute_next_boundary");out<<"}";}out<<"]\n";}
